  if (st->EXPLODE_COLOR_1) XFreeGC (dpy, st->EXPLODE_COLOR_1);
  if (st->EXPLODE_COLOR_2) XFreeGC (dpy, st->EXPLODE_COLOR_2);
  if (st->stars) free (st->stars);
  if (st->mother) {
    free (st->mother->lasers);
    free (st->mother);
  }
  for (i = 0; i < st->NUM_ROBOTS; i++)
    free (st->robots[i].lasers);
  free (st->robots);
  free (st);
}


